def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            y0, y1 = min(y for y,x in comp), max(y for y,x in comp)
            x0, x1 = min(x for y,x in comp), max(x for y,x in comp)
            cells = set(comp)
            perimeter = {(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1)
                         if y in (y0,y1) or x in (x0,x1)}
            if len(perimeter) > 0 and perimeter <= cells:
                for y in range(y0+1,y1):
                    for x in range(x0+1,x1):
                        out[y][x] = 2
            else:
                # Fill background pockets enclosed by this non-rectangular outline.
                for y in range(y0+1,y1):
