                            q2 = [(y,x)]; visited = {(y,x)}; touches_edge = False
                            while q2:
                                yy,xx=q2.pop()
                                if yy in (0,h-1) or xx in (0,w-1): touches_edge=True
                                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                                    ny,nx=yy+dy,xx+dx
                                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==bg and (ny,nx) not in visited:
                                        visited.add((ny,nx)); q2.append((ny,nx))
                            if not touches_edge:
                                for yy,xx in visited: out[yy][xx]=7
    return out
'''
